import http.server, threading, subprocess, pathlib, json, time
ROOT=pathlib.Path(__file__).resolve().parent
class Handler(http.server.BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def log_message(self,*a): pass
 def do_GET(self): self.handle_request()
 def do_HEAD(self): self.handle_request()
 def do_POST(self): self.handle_request()
 def handle_request(self):
  lab=self.server.lab
  lab.requests.append((self.command,self.path,dict(self.headers)))
  response=lab.respond(self.path, self.command, self.headers)
  code,body,*other=response
  if isinstance(body,str): body=body.encode()
  headers={'Content-Length':str(len(body)), 'Content-Type':'text/html'}
  if other: headers.update(other[0])
  self.send_response(code)
  for k,v in headers.items():
   if v is not None: self.send_header(k,v)
  self.end_headers()
  if self.command!='HEAD':
   try: self.wfile.write(body)
   except (BrokenPipeError,ConnectionResetError): pass
class Lab:
 def __init__(self, respond=None):
  self.respond=respond or (lambda p,m,h:(404,'missing'))
  self.requests=[]
  self.server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler)
  self.server.daemon_threads=True
  self.server.lab=self
  threading.Thread(target=self.server.serve_forever,daemon=True).start()
  self.url='http://127.0.0.1:'+str(self.server.server_port)
  self.prefix=ROOT/('lab'+str(self.server.server_port))
 def run(self,words='a\nb\n',args=[],base=None,files=True,log=True,no_color=True,more_default=[],timeout=15):
  self.requests.clear()
  wf=self.prefix.with_suffix('.words')
  wf.write_text(words)
  cmd=['./executable',self.url+(base or ''),'-w',str(wf),'--no-proxy','-t','1','-T','1']
  if no_color: cmd+=['--no-color']
  if files: cmd+=['--output-all',str(self.prefix)]
  cmd+=more_default+args
  try:
   proc=subprocess.run(cmd,capture_output=True,timeout=timeout)
   rc,out,err=proc.returncode,proc.stdout.decode(errors='replace'),proc.stderr.decode(errors='replace')
  except subprocess.TimeoutExpired as e:
   rc,out,err='TIMEOUT',(e.stdout or b'').decode(errors='replace'),(e.stderr or b'').decode(errors='replace')
  reports={}
  if files:
   for ext in ['json','txt','xml']:
    f=self.prefix.with_suffix('.'+ext)
    if f.exists(): reports[ext]=f.read_text()
  r={'code':rc, 'out':out, 'err':err,'requests':list(self.requests),'reports':reports}
  if log:
   print('ARGS',args,'WORDS',repr(words),'BASE',base,'STATUS',rc,'\nOUT',repr(out),'\nERR',repr(err),'\nREQS',[(m,p) for m,p,h in self.requests],flush=True)
  return r
