"""Small, shared console and failure helpers."""
import os
import sys
import threading
import time

VERSION = 'Dirble 1.4.2 (commit c11e5cd, build 2026-06-11)'
_lock = threading.RLock()


def write(text, err=False):
    with _lock:
        stream = sys.stderr if err else sys.stdout
        stream.write(text)
        stream.flush()


def line(text='', err=False):
    write(str(text) + '\n', err)


class Failure(Exception):
    def __init__(self, code=101):
        self.code = code


def panic(location, message, name='main', tid=None, note=True):
    if tid is None:
        tid = os.getpid() if name == 'main' else threading.get_native_id()
    text = "\nthread '{}' ({}) panicked at {}:\n{}\n".format(name, tid, location, message)
    if note:
        text += 'note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n'
    write(text, err=True)


def fail(location, message):
    panic(location, message)
    raise Failure()


class Logger:
    def __init__(self, config):
        self.level = config.verbose
        self.silent = config.silent

    def info(self, message):
        if not self.silent:
            line('[INFO] ' + message)

    def warn(self, message):
        line('[WARN] ' + message)

    def debug(self, thread, module, message):
        if self.level:
            line('{} [DEBUG] ({}) dirble{}: {}'.format(
                time.strftime('%H:%M:%S'), thread, '::' + module if module else '', message))

    def trace(self, thread, module, location, message):
        if self.level >= 2:
            line('{} [TRACE] ({}) dirble::{}: [{}] {}'.format(
                time.strftime('%H:%M:%S'), thread, module, location, message))
