"""URL parsing and reference resolution used by the scanner.

The scanner keeps a display URL separately from the wire representation: a
fragment, for example, remains useful in a report but is never sent to a server.
"""
import ipaddress
import re
import urllib.parse


class UrlError(ValueError):
    pass


SCHEME = re.compile(r'^[a-zA-Z][a-zA-Z0-9+.-]*:')
SPECIAL = {'http': 80, 'https': 443, 'ftp': 21, 'ws': 80, 'wss': 443, 'file': None}


def clean(s):
    return s.strip(''.join(map(chr, range(33)))).replace('\r', '').replace('\n', '').replace('\t', '')


def encode(s, kind):
    # These are the characters which the corresponding URL component retains.
    safe = "!$&'()*+,-./:;=@_~%[]^|\\"
    if kind == 'path':
        safe = safe.replace('\\', '')
    elif kind == 'query':
        safe += '?`{}'
        safe = safe.replace("'", '')
    elif kind == 'fragment':
        safe += '?{}#'
    elif kind == 'opaque':
        safe += '?`{}'
    return urllib.parse.quote(s, safe=safe, encoding='utf-8', errors='replace')


def path_normalize(path):
    # Dot-segment removal, without coalescing consecutive slashes.
    leading = path.startswith('/')
    parts = path.split('/')
    out = []
    for i, part in enumerate(parts):
        p = re.sub(r'%2e', '.', part, flags=re.I)
        if p == '.':
            if i == len(parts) - 1:
                out.append('')
        elif p == '..':
            if out and not (len(out) == 1 and out[0] == ''):
                out.pop()
            if i == len(parts) - 1:
                out.append('')
        else:
            out.append(part)
    result = '/'.join(out)
    if leading and not result.startswith('/'):
        result = '/' + result
    return result


def _ipv4(host):
    items = host.rstrip('.').split('.')
    if not items or len(items) > 4:
        raise UrlError('invalid IPv4 address')
    nums = []
    for item in items:
        if not item:
            raise UrlError('invalid IPv4 address')
        try:
            if item.lower().startswith('0x'):
                n = int(item[2:] or '0', 16)
            elif len(item) > 1 and item.startswith('0'):
                n = int(item[1:] or '0', 8)
            else:
                n = int(item, 10)
        except ValueError:
            raise UrlError('invalid IPv4 address') from None
        if n < 0:
            raise UrlError('invalid IPv4 address')
        nums.append(n)
    if any(n > 255 for n in nums[:-1]) or nums[-1] >= 256 ** (5 - len(nums)):
        raise UrlError('invalid IPv4 address')
    n = nums[-1]
    for i, part in enumerate(nums[:-1]):
        n += part * 256 ** (3 - i)
    return str(ipaddress.IPv4Address(n))


def _authority(raw, scheme):
    user = ''
    if '@' in raw:
        user, raw = raw.rsplit('@', 1)
        user = user.replace('@', '%40')
        if ':' in user:
            u, p = user.split(':', 1)
            u = urllib.parse.quote(u, safe="!$&'()*+,-._~%")
            p = urllib.parse.quote(p, safe="!$&'()*+,-._~%")
            user = u + (':' + p if p else '')
        else:
            user = urllib.parse.quote(user, safe="!$&'()*+,-._~%")
        if user:
            user += '@'
    port = None
    if raw.startswith('['):
        end = raw.find(']')
        if end < 0:
            raise UrlError('invalid IPv6 address')
        try:
            host = '[' + str(ipaddress.IPv6Address(raw[1:end])) + ']'
        except ValueError:
            raise UrlError('invalid IPv6 address') from None
        rem = raw[end + 1:]
        if rem:
            if not rem.startswith(':'):
                raise UrlError('invalid port number')
            port = rem[1:]
    else:
        host = raw
        if ':' in host:
            host, port = host.rsplit(':', 1)
        if scheme in SPECIAL:
            try:
                host = urllib.parse.unquote(host, errors='strict')
            except (ValueError, UnicodeError):
                raise UrlError('invalid international domain name') from None
            if any(ord(c) <= 32 or c in '#/:<>?@[\\]^|' or ord(c) == 127 for c in host):
                raise UrlError('invalid international domain name')
            try:
                host = host.encode('idna').decode('ascii').lower()
            except UnicodeError:
                raise UrlError('invalid international domain name') from None
            last = host.rstrip('.').split('.')[-1]
            if last and (last.isdigit() or (last.lower().startswith('0x') and all(c in '0123456789abcdefABCDEF' for c in last[2:]))):
                host = _ipv4(host)
    if not host and scheme != 'file':
        raise UrlError('empty host')
    if port is not None and port != '':
        if not port.isascii() or not port.isdigit() or int(port) > 65535:
            raise UrlError('invalid port number')
        port = int(port)
        if scheme in SPECIAL and port == SPECIAL[scheme]:
            port = None
    else:
        port = None
    if scheme == 'file' and host == 'localhost':
        host = ''
    return user + host + (':' + str(port) if port is not None else '')


def normalize(value):
    text = clean(value)
    match = SCHEME.match(text)
    if not match:
        raise UrlError('relative URL without a base')
    scheme = text[:match.end() - 1].lower()
    rest = text[match.end():]
    fragment = None
    if '#' in rest:
        rest, fragment = rest.split('#', 1)
    query = None
    if '?' in rest:
        rest, query = rest.split('?', 1)
    if scheme in SPECIAL:
        rest = rest.replace('\\', '/')
    authority = None
    if scheme in SPECIAL and scheme != 'file':
        rest = rest.lstrip('/')
        if '/' in rest:
            authority, path = rest.split('/', 1)
            path = '/' + path
        else:
            authority, path = rest, '/'
        authority = _authority(authority, scheme)
    elif rest.startswith('//'):
        rest = rest[2:]
        if '/' in rest:
            authority, path = rest.split('/', 1)
            path = '/' + path
        else:
            authority, path = rest, '/' if scheme == 'file' else ''
        authority = _authority(authority, scheme)
    elif scheme == 'file':
        authority, path = '', '/' + rest.lstrip('/')
    else:
        path = rest
    if authority is not None:
        path = encode(path_normalize(path), 'path')
        result = scheme + '://' + authority + path
    elif path.startswith('/'):
        result = scheme + ':' + encode(path_normalize(path), 'path')
    else:
        result = scheme + ':' + encode(path, 'opaque')
    if query is not None:
        result += '?' + encode(query, 'query')
    if fragment is not None:
        result += '#' + encode(fragment, 'fragment')
    return result


def split(url):
    try:
        return urllib.parse.urlsplit(url)
    except ValueError as e:
        raise UrlError(str(e)) from None


def join(base, value):
    ref = clean(value)
    bp = split(base)
    if bp.scheme in SPECIAL:
        # Backslashes delimit a path, but not the query or fragment.
        head, sep, tail = ref.partition('?')
        if not sep:
            head, sep, tail = ref.partition('#')
        ref = head.replace('\\', '/') + (sep + tail if sep else '')
    match = SCHEME.match(ref)
    if match:
        new_scheme = ref[:match.end() - 1].lower()
        if new_scheme == bp.scheme and new_scheme in SPECIAL and not ref[match.end():].startswith('//'):
            ref = ref[match.end():]
        else:
            return normalize(ref)
    if not bp.netloc and bp.scheme != 'file' and not bp.path.startswith('/'):
        if ref.startswith('#'):
            return base.split('#', 1)[0] + '#' + encode(ref[1:], 'fragment')
        raise UrlError('relative URL with a cannot-be-a-base base')
    if ref.startswith('//'):
        return normalize(bp.scheme + ':' + ref)
    prefix = bp.scheme + '://' + bp.netloc if bp.netloc or bp.scheme == 'file' else bp.scheme + ':'
    if ref.startswith('/'):
        return normalize(prefix + ref)
    if ref.startswith('?'):
        return normalize(prefix + bp.path + ref)
    if ref.startswith('#'):
        return normalize(base.split('#', 1)[0] + ref)
    if not ref:
        return base.split('#', 1)[0]
    path = bp.path[:bp.path.rfind('/') + 1]
    return normalize(prefix + path + ref)


def depth(url):
    return len([p for p in split(url).path.split('/') if p])
