    opt('cookie', 'c', 'cookie', repeat=True), opt('header', 'H', 'header', repeat=True),
    opt('silent', 'S'), opt('verbose', 'v', kind='count', default=0),
    opt('code-blacklist', 'B', 'code_blacklist', kind='u32', repeat=True, many=True),
    opt('disable-validator'),
