SHORT = {o.short: o for o in OPTIONS if o.short}


def help_text(prog):
    here = Path(__file__).parent
    try:
        text = (here / 'help.txt').read_text()
    except (OSError, NotADirectoryError):
        with zipfile.ZipFile(sys.argv[0]) as z:
            text = z.read('help.txt').decode()
