def _jaro_winkler(a, b):
    # Used only for the small spelling hints in argument diagnostics.
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    window = max(len(a), len(b)) // 2 - 1
    window = max(0, window)
    am, bm = [False] * len(a), [False] * len(b)
    matches = 0
    for i, c in enumerate(a):
        for j in range(max(0, i - window), min(len(b), i + window + 1)):
            if not bm[j] and c == b[j]:
                am[i], bm[j] = True, True
                matches += 1
                break
