        return 0.0
    s1 = [c for c, m in zip(a, am) if m]
    s2 = [c for c, m in zip(b, bm) if m]
    trans = sum(x != y for x, y in zip(s1, s2)) / 2
    score = (matches / len(a) + matches / len(b) + (matches - trans) / matches) / 3
