"""Report storage and the three public serialization formats."""
import json
import os
import sys
import threading
from dataclasses import dataclass, field
from pathlib import Path

from runtime import Failure, VERSION, fail, line, panic, write
from urls import split


@dataclass
class Node:
    entries: list = field(default_factory=list)
    children: dict = field(default_factory=dict)

    def flatten(self, level=0):
        for entry in sorted(self.entries, key=lambda r: r.url):
            yield entry, level
        for key in sorted(self.children):
            yield from self.children[key].flatten(level + 1)


def description(r):
    mark = 'L' if r.is_listable else 'D' if r.is_directory else '+'
    if r.found_from_listable:
        details = 'SCRAPED'
    else:
        details = 'CODE:{}|SIZE:{}'.format(r.code, r.size)
        if r.redirect_url:
            details += '|DEST:' + r.redirect_url
    return '{} {} ({})'.format(mark, r.url, details)


def visible(r, c):
    return c.show_htaccess or r.code != 403 or '.ht' not in r.url


def attr(value):
    return str(value).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')


class Reports:
    def __init__(self, config):
        self.c = config
        self.console = sys.stdout.isatty()
        self.color = self.console and not config.no_color and 'NO_COLOR' not in os.environ
        self.files = {}
        self.roots = {url: Node() for url in config.targets}
        self.lock = threading.RLock()
        # Opening all requested files here also establishes early I/O errors,
        # rather than discovering an unwritable output after the scan.
        for kind, name in [('txt', config.output_file), ('json', config.json_file), ('xml', config.xml_file)]:
            if name is None:
                continue
            try:
                self.files[kind] = open(name, 'w', encoding='utf-8', newline='')
            except OSError as e:
                fail('src/output.rs:231:21', "couldn't create {}: {} (os error {})".format(name, e.strerror, e.errno))

    def banner(self):
        if not self.console or self.c.silent:
            return
        line(VERSION)
        line('Developed by Izzy Whistlecroft')
        line('Targets: ' + ', '.join(self.c.targets))
        line('Wordlists: ' + ', '.join(self.c.wordlist))
        prefixes = [x for x in self.c.prefixes if x]
        extensions = [x for x in self.c.extensions if x]
        line('Prefixes: ' + ', '.join(prefixes) if prefixes else 'No Prefixes')
        line('Extensions: ' + ', '.join(extensions) if extensions else 'No Extensions')
        if self.c.hide_lengths:
            line('Lengths hidden: ' + ', '.join(self.c.hide_lengths))
        else:
            line('No lengths hidden')
        line()

    def paint(self, r):
        text = description(r)
        if not self.color:
            return text
        # Terminal coloring is kept outside stored report data.
        color = '32' if r.code < 300 else '33' if r.code < 400 else '31'
        return '\x1b[' + color + 'm' + text + '\x1b[0m'

    def add(self, root, r):
        with self.lock:
            if root not in self.roots:
                self.roots[root] = Node()
            node = self.roots[root]
            rootpath = split(root).path
            path = split(r.url).path
            parent = path[:path.rfind('/') + 1]
            if parent.startswith(rootpath):
                relative = parent[len(rootpath):]
            else:
                relative = parent.lstrip('/')
            if relative.endswith('/'):
                relative = relative[:-1]
            if relative:
                for part in relative.split('/'):
                    node = node.children.setdefault(part, Node())
            node.entries.append(r)
            if not self.c.silent and visible(r, self.c):
                line(self.paint(r))

    def _records(self):
        for root in sorted(self.roots):
            yield from (r for r, depth in self.roots[root].flatten())

    def text(self, terminal=False):
        result = ''
        for root in sorted(self.roots):
            result += 'Dirble Scan Report for ' + root + ':\n'
            for r, depth in self.roots[root].flatten():
                if not visible(r, self.c):
                    continue
                if r.is_directory:
                    result += '\n'
                prefix = '  ' * (depth + 1) if terminal else ''
                result += prefix + (self.paint(r) if terminal else description(r)) + '\n'
            result += '\n'
        return result

    def finish(self):
        if self.console:
            write('\n' + self.text(terminal=True).rstrip('\n') + '\n')
        if 'txt' in self.files:
            self.files['txt'].write(self.text())
            self.files['txt'].flush()
        records = list(self._records())
        if 'json' in self.files:
            f = self.files['json']
            f.write('[')
            f.flush()
            if not records:
                panic('src/output.rs:137:37',
                      'range end index 18446744073709551615 out of range for slice of length 0',
                      name='<unnamed>', tid=os.getpid() + 3)
                panic('src/lib.rs:329:26', 'called `Result::unwrap()` on an `Err` value: Any { .. }', note=False)
                raise Failure()
            f.write(',\n'.join(json.dumps(r.data(), ensure_ascii=False, separators=(',', ':')) for r in records))
            f.write(']')
            f.flush()
        if 'xml' in self.files:
            f = self.files['xml']
            f.write('<?xml version="1.0" encoding="UTF-8"?>\n<dirble_scan>\n')
            for r in records:
                data = r.data()
                names = [('url', 'url'), ('code', 'code'), ('size', 'content_len'),
                         ('is_directory', 'is_directory'), ('is_listable', 'is_listable'),
                         ('redirect_url', 'redirect_url'), ('found_from_listable', 'found_from_listable')]
                fields = []
                for key, label in names:
                    value = data[key]
                    if isinstance(value, bool):
                        value = str(value).lower()
                    fields.append(label + '="' + attr(value) + '"')
                f.write('<path ' + ' '.join(fields) + '/>\n')
            f.write('</dirble_scan>')
            f.flush()

    def close(self):
        for f in self.files.values():
            f.close()
