"""Entry point for the independently implemented scanner."""
import sys
from options import parse, prepare
from report import Reports
from runtime import Failure
from scan import Scanner


def main(argv):
    reports = None
    try:
        config = prepare(parse(argv))
        reports = Reports(config)
        reports.banner()
        Scanner(config, reports).run()
        reports.finish()
        return 0
    except Failure as e:
        return e.code
    except KeyboardInterrupt:
        return 130
    except BrokenPipeError:
        return 0
    finally:
        if reports:
            reports.close()


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
